WITH base AS (WITH raw AS (SELECT CAST(e.global_position AS TEXT) source_record_id,a.semantic_code,json_extract(e.payload_json,'$.claimRef') case_id,json_extract(e.payload_json,'$.effectiveAt') timestamp,json_extract(e.metadata_json,'$.actor') actor,json_extract(e.payload_json,'$.objectRefs') object_refs,'event_store' source_table,e.correlation_id FROM event_store e JOIN event_type_alias a USING(event_type,schema_version) WHERE e.stream_type<>'TECHNICAL' UNION ALL SELECT result_id,semantic_code,json_extract(payload_json,'$.claimRef'),json_extract(payload_json,'$.effectiveAt'),actor_code,json_extract(payload_json,'$.objectRefs'),'command_result',correlation_id FROM command_result WHERE result_code='APPLIED' UNION ALL SELECT message_id,semantic_code,json_extract(payload_json,'$.claimRef'),json_extract(payload_json,'$.effectiveAt'),'EXTERNAL',json_extract(payload_json,'$.objectRefs'),'inbox_message',correlation_id FROM inbox_message WHERE processed_flag=1 UNION ALL SELECT document_id,semantic_code,json_extract(payload_json,'$.claimRef'),json_extract(payload_json,'$.effectiveAt'),'INDEXER',json_extract(payload_json,'$.objectRefs'),'document_index',correlation_id FROM document_index WHERE index_status='ACTIVE'), fused AS (SELECT *,ROW_NUMBER() OVER(PARTITION BY correlation_id,semantic_code ORDER BY CASE source_table WHEN 'event_store' THEN 1 ELSE 2 END,CASE WHEN source_table='event_store' THEN printf('%020d',CAST(source_record_id AS INTEGER)) ELSE source_record_id END) rn FROM raw), mapped AS (SELECT *,CASE semantic_code WHEN 'CS001' THEN 'Claim Reported' WHEN 'CS002' THEN 'Incident Registered' WHEN 'CS003' THEN 'Claim Acknowledged' WHEN 'CS004' THEN 'Policy Located' WHEN 'CS005' THEN 'Coverage Check Started' WHEN 'CS006' THEN 'Coverage Confirmed' WHEN 'CS007' THEN 'Coverage Denied' WHEN 'CS008' THEN 'Exposure Opened' WHEN 'CS009' THEN 'Exposure Classified' WHEN 'CS010' THEN 'Exposure Reclassified' WHEN 'CS011' THEN 'Adjuster Assigned' WHEN 'CS012' THEN 'Adjuster Reassigned' WHEN 'CS013' THEN 'Inspection Scheduled' WHEN 'CS014' THEN 'Inspection Rescheduled' WHEN 'CS015' THEN 'Inspection Completed' WHEN 'CS016' THEN 'Damage Item Added' WHEN 'CS017' THEN 'Damage Item Updated' WHEN 'CS018' THEN 'Evidence Requested' WHEN 'CS019' THEN 'Evidence Received' WHEN 'CS020' THEN 'Evidence Validated' WHEN 'CS021' THEN 'Evidence Rejected' WHEN 'CS022' THEN 'Estimate Requested' WHEN 'CS023' THEN 'Estimate Received' WHEN 'CS024' THEN 'Estimate Revised' WHEN 'CS025' THEN 'Estimate Approved' WHEN 'CS026' THEN 'Reserve Established' WHEN 'CS027' THEN 'Reserve Increased' WHEN 'CS028' THEN 'Reserve Decreased' WHEN 'CS029' THEN 'Reserve Released' WHEN 'CS030' THEN 'Fraud Score Calculated' WHEN 'CS031' THEN 'Fraud Investigation Opened' WHEN 'CS032' THEN 'Fraud Investigation Cleared' WHEN 'CS033' THEN 'Fraud Case Referred' WHEN 'CS034' THEN 'Liability Accepted' WHEN 'CS035' THEN 'Liability Partially Accepted' WHEN 'CS036' THEN 'Liability Denied' WHEN 'CS037' THEN 'Repair Authorized' WHEN 'CS038' THEN 'Repair Started' WHEN 'CS039' THEN 'Repair Completed' WHEN 'CS040' THEN 'Repair Reopened' WHEN 'CS041' THEN 'Payment Proposed' WHEN 'CS042' THEN 'Payment Approved' WHEN 'CS043' THEN 'Payment Issued' WHEN 'CS044' THEN 'Payment Failed' WHEN 'CS045' THEN 'Payment Reissued' WHEN 'CS046' THEN 'Payment Canceled' WHEN 'CS047' THEN 'Recovery Identified' WHEN 'CS048' THEN 'Recovery Demand Sent' WHEN 'CS049' THEN 'Recovery Received' WHEN 'CS050' THEN 'Litigation Opened' WHEN 'CS051' THEN 'Hearing Scheduled' WHEN 'CS052' THEN 'Claim Settled' WHEN 'CS053' THEN 'Customer Contacted' WHEN 'CS054' THEN 'Complaint Opened' WHEN 'CS055' THEN 'Complaint Resolved' WHEN 'CS056' THEN 'Claim Closed' WHEN 'CS057' THEN 'Claim Reopened' WHEN 'CS058' THEN 'Claim Archived' END activity FROM fused WHERE rn=1) SELECT case_id,activity,timestamp,source_table,source_record_id,actor,object_refs FROM mapped WHERE activity IS NOT NULL ORDER BY case_id,timestamp,source_record_id), selected AS (SELECT DISTINCT case_id FROM base WHERE activity IN ('Claim Reopened','Coverage Denied','Evidence Rejected','Fraud Case Referred','Liability Denied','Payment Canceled','Payment Failed','Repair Reopened')) SELECT base.*,CASE WHEN activity IN ('Claim Reopened','Coverage Denied','Evidence Rejected','Fraud Case Referred','Liability Denied','Payment Canceled','Payment Failed','Repair Reopened') THEN 1 ELSE 0 END is_exception_event FROM base JOIN selected USING(case_id) ORDER BY case_id,timestamp,source_record_id;
